import topicsData from './topics.generated.json';

/**
 * The light list of topics the home screen needs, without the cards themselves. Generated by
 * `pnpm topics` from the card files.
 */

export type Topic = {
  id: string;
  unit: string;
  /** The topic's short name, as listed on the home screen. */
  topic: string;
  /** The same name in French, from the card's French overlay; absent while it has none. */
  topicFr?: string;
  /** The card file in `src/content/cards/` that declares the card, without `.ts`. */
  file: string;
  /** The track modules whose quiz questions follow this card, as `m05`. */
  mcqModules: string[];
};

/** Every topic, in learning order. */
export const TOPICS: readonly Topic[] = topicsData;

export { UNITS } from './units.ts';
